// A few stories from the wider world, two or three a year
hist.push(
{d:'1960-11-03',t:'world',pic:'gavel',h:'LADY CHATTERLEY NOT GUILTY',b:'A jury at the Old Bailey clears Penguin Books of obscenity. The prosecution had asked whether it was a book "you would wish your wife or your servants to read".'},
{d:'1960-12-10',t:'world',pic:'tv',h:'NEW SERIAL FROM THE NORTH',b:'Granada Television launches a twice-weekly serial about the residents of a Salford terrace. It is called Coronation Street.'},
{d:'1961-01-02',t:'world',pic:'coins',h:'FAREWELL TO THE FARTHING',b:'The farthing ceased to be legal tender at midnight on New Year\'s Eve. The wren on the back flies no more.'},
{d:'1961-03-16',t:'world',pic:'car',h:'THE E-TYPE',b:'Jaguar unveils its new E-Type at the Geneva motor show. They say Enzo Ferrari called it the most beautiful car ever made.'},
{d:'1961-08-14',t:'world',pic:'flag',h:'A WALL ACROSS BERLIN',b:'East German troops seal the border through Berlin with barbed wire. Concrete follows.'},
{d:'1962-05-26',t:'world',pic:'flag',h:"COVENTRY'S NEW CATHEDRAL",b:'The new cathedral, built beside the ruins of the old one destroyed in the Blitz, is consecrated in the presence of the Queen.'},
{d:'1962-10-06',t:'world',pic:'film',h:'BOND IS ON THE SCREEN',b:'Sean Connery stars as James Bond in Dr. No, which opens at the London Pavilion.'},
{d:'1962-10-29',t:'world',pic:'rocket',h:'CUBA: THE WORLD BREATHES AGAIN',b:'Mr Khrushchev agrees to remove Soviet missiles from Cuba after thirteen days of crisis.'},
{d:'1963-06-05',t:'world',pic:'ballot',h:'PROFUMO RESIGNS',b:'The Secretary of State for War resigns after admitting he misled the House of Commons.'},
{d:'1963-08-09',t:'world',pic:'train',h:'THE GREAT TRAIN ROBBERY',b:'A gang stops the Glasgow to London mail train in Buckinghamshire and gets away with more than two and a half million pounds.'},
{d:'1963-11-24',t:'world',pic:'tv',h:'A TIME MACHINE ON THE BBC',b:'A new Saturday teatime serial, Doctor Who, begins on the BBC.'},
{d:'1964-02-08',t:'world',pic:'plane',h:'THE BEATLES CONQUER AMERICA',b:'Screaming crowds greet the Beatles at New York\'s airport. Seventy-three million Americans are expected to watch them on The Ed Sullivan Show.'},
{d:'1964-03-29',t:'world',pic:'ship',h:'PIRATE RADIO',b:'Radio Caroline begins broadcasting pop music from a ship anchored off the Essex coast.'},
{d:'1964-05-19',t:'world',pic:'scooter',h:'MODS AND ROCKERS',b:'Scooters and motorbikes clash on the beaches at Margate and Brighton over the Whitsun bank holiday.'},
{d:'1965-06-12',t:'world',pic:'record',h:'MBEs FOR THE BEATLES',b:'The Beatles are to be made Members of the Order of the British Empire. Several war heroes send their medals back in protest.'},
{d:'1965-10-09',t:'world',pic:'tower',h:'THE POST OFFICE TOWER',b:'London\'s tallest building is opened: over six hundred feet of glass and concrete, with a revolving restaurant near the top.'},
{d:'1966-04-01',t:'world',pic:'ballot',h:'WILSON WINS AGAIN',b:'Labour are returned at the general election with a majority of ninety-six.'},
{d:'1966-06-29',t:'world',pic:'coins',h:'THE FIRST CREDIT CARD',b:'Barclays launches the Barclaycard, the first credit card in Britain.'},
{d:'1967-05-29',t:'world',pic:'ship',h:'CHICHESTER HOME',b:'Francis Chichester sails into Plymouth after going round the world alone in Gipsy Moth IV. A quarter of a million people line the Hoe.'},
{d:'1967-07-02',t:'world',pic:'tv',h:'TELEVISION IN COLOUR',b:'BBC Two begins colour broadcasts, starting with the tennis from Wimbledon.'},
{d:'1967-11-19',t:'world',pic:'coins',h:'THE POUND IS DEVALUED',b:'The pound is devalued by fourteen per cent. The Prime Minister insists that the pound in your pocket has not been devalued.'},
{d:'1968-08-31',t:'world',pic:'record',h:'HEY JUDE',b:'The Beatles release Hey Jude, all seven minutes of it.'},
{d:'1968-10-16',t:'world',pic:'trophy',h:'HEMERY TAKES GOLD',b:'David Hemery wins the 400 metres hurdles at the Mexico City Olympics in a world record time.'},
{d:'1968-12-25',t:'world',pic:'moon',h:'CHRISTMAS AROUND THE MOON',b:'Apollo 8 becomes the first manned spacecraft to orbit the Moon. On Christmas Eve the crew read from the Book of Genesis.'},
{d:'1969-05-03',t:'world',pic:'ship',h:'THE QE2 SETS SAIL',b:'The Queen Elizabeth 2 leaves Southampton on her maiden voyage to New York.'},
{d:'1969-07-02',t:'world',pic:'flag',h:'A PRINCE AT CAERNARFON',b:'Prince Charles is invested as Prince of Wales at Caernarfon Castle.'},
{d:'1969-10-06',t:'world',pic:'tv',h:'SOMETHING COMPLETELY DIFFERENT',b:"A new comedy programme, Monty Python's Flying Circus, begins on BBC One."},
{d:'1970-04-11',t:'world',pic:'record',h:'THE BEATLES SPLIT',b:'Paul McCartney announces that he has left the Beatles.'},
{d:'1970-04-18',t:'world',pic:'rocket',h:'APOLLO 13 HOME SAFE',b:'The crippled Apollo 13 splashes down safely in the Pacific after an explosion on the way to the Moon.'}
);

